import java.util.Scanner

class Sticks {
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val s = Scanner(System.`in`)
            val a = IntArray(6)
            var y = 0
            var no = 0
            for (i in 0 until 6) {
                a[i] = s.nextInt()
            }

            val b = IntArray(10)

            for (i in 0 until 6) {
                val x = a[i]
                b[x]++
            }

            for (i in 1 until 10) {
                if (b[i] == 4) {
                    for (j in 1 until 10) {
                        if (b[j] == 2) {
                            y++
                        } else {
                            val x = 1
                        }
                    }
                } else if (b[i] > 4) {
                    if (b[i] == 6) {
                        y++
                    } else {
                        val x = 1
                    }
                } else {
                    no++
                }
            }

            if (no == 9) {
                println("Alien")
            } else {
                if (y == 1) {
                    println("Elephant")
                } else {
                    println("Bear")
                }
            }
        }
    }
}

